<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingSuperAdmin} from './permissions';
const voucherSuperAdmin=useAccountingSuperAdmin();
import {useAccountingLiveRefresh} from './workspaceRealtime';
import AccountingCurrencyFields from './AccountingCurrencyFields.vue';
import {needsApproval,approvalTypes,selectedApprovalTypes} from './approvalPolicy';
import {addRowOnEnter} from './entryRows';
import {useAccountingPermissions} from './permissions';
const can=useAccountingPermissions();
import AccountingSelect from './AccountingSelect.vue';
import AccountingApprovalPanel from './AccountingApprovalPanel.vue';
import CashBasisReview from './CashBasisReview.vue';
import AccountingStatement from './AccountingStatement.vue';
import {requestKey} from './requestKey';
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import AccountingDocument from './AccountingDocument.vue';
import AdminDialog from '../../AdminDialog.vue';
const props=defineProps<{openId?:number;globalPolicy?:any;isSuperAdmin?:boolean;section:string;company:number;companyName:string;initialAccount?:string;book:any;accounts:any[];canManage:boolean;canAdmin:boolean;csrf?:string}>();
const emit=defineEmits(['changed','notice','ledger','setup','chart','imprest']);
const today=new Date().toLocaleDateString('en-CA');
const initialParams=new URLSearchParams(location.search);
const initialDate=(key:string,fallback:string)=>/^\d{4}-\d{2}-\d{2}$/.test(initialParams.get(key)||'')?initialParams.get(key)!:fallback;
const loading=ref(false),busy=ref(false),exporting=ref(false),error=ref(''),formError=ref(''),page=ref(1),search=ref(''),status=ref(''),from=ref(initialDate('from',today.slice(0,7)+'-01')),to=ref(initialDate('to',today)),accountId=ref(props.initialAccount||''),result=ref<any>(null),editor=ref<any>(null),dialog=ref(''),reverseDate=ref(today),reason=ref('');
const cashReviewId=ref<number|null>(null);
async function reviewSaved(message:string){cashReviewId.value=null;emit('notice',message);await load();}
const requiresApproval=computed(()=>needsApproval(props.book,editor.value?.kind||'general'));
const settings=ref<any>({}),savedSignature=ref('');let generation=0;
function signature(j:any){return JSON.stringify([j.currency,j.exchange_rate,j.posting_date,j.kind,j.reference||'',j.remarks,j.lines.map((l:any)=>[l.account_id,String(l.debit),String(l.credit),l.description||'',l.party_id||null])]);}
function reviewPosting(){if(signature(editor.value)!==savedSignature.value){formError.value='Save the draft changes before reviewing posting.';return;}dialog.value='post';}
const titles:Record<string,string>={journals:'Journal entries',ledger:'General Ledger',trial:'Trial Balance',profit:'Profit and Loss',balance:'Balance Sheet',books:'Company books',audit:'Audit history',receivables:'Accounts receivable',payables:'Accounts payable'};
const aging=computed(()=>['receivables','payables'].includes(props.section));
const ledgerAccounts=computed(()=>props.accounts.filter(a=>!a.imprest_fund&&!a.is_group&&a.active&&(!['Receivable','Payable'].includes(a.account_type)||!!a.party_kind)));
const allLedgers=computed(()=>props.accounts.filter(a=>!a.is_group));
const trialColumns=ref(initialParams.get('trial_columns')==='2'?'2':'6'),profitBasis=ref(initialParams.get('basis')==='cash'?'cash':'accrual');
const trialFields=computed(()=>trialColumns.value==='2'?[{key:'closing_debit',label:'Closing debit'},{key:'closing_credit',label:'Closing credit'}]:[{key:'opening_debit',label:'Opening debit'},{key:'opening_credit',label:'Opening credit'},{key:'debit',label:'Period debit'},{key:'credit',label:'Period credit'},{key:'closing_debit',label:'Closing debit'},{key:'closing_credit',label:'Closing credit'}]);
const trialTotal=(key:string)=>{const total=(result.value?.rows||[]).reduce((n:number,r:any)=>{const text=String(r[key]||'0');const [whole,fraction='']=text.replace('-','').split('.');return n+(Number(whole)*100+Number(fraction.padEnd(2,'0')))*(text.startsWith('-')?-1:1);},0);return amount(total/100);};
const rows=computed(()=>props.section==='journals'||props.section==='audit'?result.value?.data||[]:props.section==='ledger'?result.value?.entries?.data||[]:result.value?.rows||[]);
const lastPage=computed(()=>props.section==='ledger'?result.value?.entries?.last_page||1:result.value?.last_page||1);
function selectZero(event:Event){const input=event.target as HTMLInputElement;if(input.value&&Number(input.value)===0)input.select();}
function amountInput(event:Event,line:any,side:'debit'|'credit'){
 const input=event.target as HTMLInputElement;
 if(!/^\d{0,10}(?:\.\d{0,2})?$/.test(input.value)){input.value=String(line[side]??'');return;}
 line[side]=input.value;
 if(Number(line[side])>0)line[side==='debit'?'credit':'debit']='0.00';
}
function guardAmount(event:InputEvent){
 if(!event.data||event.isComposing)return;
 const input=event.target as HTMLInputElement;
 const next=input.value.slice(0,input.selectionStart??0)+event.data+input.value.slice(input.selectionEnd??input.value.length);
 if(!/^\d{0,10}(?:\.\d{0,2})?$/.test(next))event.preventDefault();
}
function finishAmount(line:any,side:'debit'|'credit'){const [whole,fraction='']=String(line[side]||'0').split('.');line[side]=String(Number(whole||'0'))+'.'+fraction.padEnd(2,'0');}
const cents=(value:any)=>{const match=String(value??'').match(/^(\d{1,10})(?:\.(\d{1,2}))?$/);return match?Number(match[1])*100+Number((match[2]||'').padEnd(2,'0')):NaN;};
const debit=computed(()=>editor.value?.lines.reduce((n:number,l:any)=>n+cents(l.debit),0)||0),credit=computed(()=>editor.value?.lines.reduce((n:number,l:any)=>n+cents(l.credit),0)||0);
const balanced=computed(()=>debit.value>0&&debit.value===credit.value);
const amount=(v:any)=>Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
const draft=computed(()=>editor.value?.status==='draft');
const approvalPending=computed(()=>editor.value?.approval&&!['returned','withdrawn'].includes(editor.value.approval.stage));
const mayEdit=computed(()=>can(editor.value?.id?'journals.update':'journals.create')&&!approvalPending.value);
const unsaved=computed(()=>!!editor.value?.id&&signature(editor.value)!==savedSignature.value);
async function api(path:string,body?:any){const r=await fetch('/accounting/api/'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(Object.values(data.errors||{}).flat().join(' ')||data.message||'Unable to complete this action.');return data;}
function reportParams(){return new URLSearchParams({company_id:String(props.company),report:props.section,...(props.section==='profit'?{basis:profitBasis.value}:{}),...(props.section==='trial'?{trial_columns:trialColumns.value}:{}),from:(props.section==='balance'||aging.value||(props.section==='trial'&&trialColumns.value==='2'))?(props.book?.start_date||to.value):from.value,to:to.value,...(accountId.value?{account_id:accountId.value}:{}),page:String(page.value)});}
async function load(){const gen=++generation;error.value='';result.value=null;if(!props.company||props.section==='books')return;if(!props.book&& !['journals','audit'].includes(props.section))return;loading.value=true;try{let data;if(props.section==='journals'){data=await api('journals?'+new URLSearchParams({company_id:String(props.company),page:String(page.value),status:status.value,search:search.value}));}else if(props.section==='audit')data=await api('audit?company_id='+props.company+'&page='+page.value);else data=await api('reports?'+reportParams());if(gen===generation)result.value=data;}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
watch(()=>[props.section,props.company,props.book],()=>{page.value=1;accountId.value=props.initialAccount||'';dialog.value='';editor.value=null;cashReviewId.value=null;settings.value={expense_open_time:'11:00',expense_close_time:'20:00',approval_required:true,version:0,currency:'PKR',start_date:today,locked_through:'',...props.globalPolicy,...props.book,approval_types:selectedApprovalTypes(props.globalPolicy||props.book)};void load().then(()=>{if(props.section==='journals'&&props.openId)void view({id:props.openId});});},{immediate:true});
watch(profitBasis,()=>{if(props.section==='profit'){page.value=1;void load();}});
onBeforeUnmount(()=>generation++);
function newJournal(){if(loading.value||busy.value)return;editor.value={company_id:props.company,request_key:requestKey(),currency:props.book?.currency||'PKR',exchange_rate:'1.000000',posting_date:today,kind:'general',reference:'',remarks:'',status:'draft',lines:[{account_id:'',debit:'0.00',credit:'0.00',description:''},{account_id:'',debit:'0.00',credit:'0.00',description:''}]};dialog.value='journal';formError.value='';}
async function view(row:any){if(loading.value||busy.value)return;formError.value='';try{const data=await api('journals?company_id='+props.company+'&id='+row.id);if(data.journal.imprest){emit('imprest',data.journal.id);return;}editor.value=data.journal;savedSignature.value=signature(editor.value);dialog.value='journal';}catch(e){error.value=(e as Error).message;}}
function journalPrintUrl(journal:any){return '/accounting/journals/'+journal.id+'/print?'+new URLSearchParams({company_id:String(props.company),version:String(journal.version),auto_print:'1'});}
function saveAndPrint(event:MouseEvent){const form=(event.currentTarget as HTMLButtonElement).form;if(form?.reportValidity())void run('save',true);}
async function run(action:string,printAfter=false){if(busy.value)return;if(action==='post'&&signature(editor.value)!==savedSignature.value){formError.value='Save all draft changes before posting.';return;}busy.value=true;formError.value='';let printWindow:Window|null=null;if(printAfter){try{printWindow=window.open('about:blank','_blank');if(printWindow){printWindow.opener=null;printWindow.document.title='Preparing journal print';printWindow.document.body.textContent='Saving journal and preparing print preview...';}}catch{printWindow=null;}}try{let response;if(action==='books')response=await api('books',{...settings.value,company_id:props.company,locked_through:settings.value.locked_through||null});else if(action==='save')response=await api('journals',{...editor.value,company_id:props.company,lines:editor.value.lines.map((line:any)=>({account_id:line.account_id,debit:line.debit,credit:line.credit,description:line.description||''}))});else if(action==='post')response=await api('journals/'+editor.value.id+'/post',{company_id:props.company,version:editor.value.version});else response=await api('journals/'+editor.value.id+'/reverse',{company_id:props.company,version:editor.value.version,posting_date:reverseDate.value,reason:reason.value});if(response.journal){editor.value=response.journal;savedSignature.value=signature(editor.value);}emit('notice',response.message);if(printAfter&&response.journal){if(printWindow&&!printWindow.closed)printWindow.location.replace(journalPrintUrl(response.journal));else emit('notice','Journal saved. Allow pop-ups and click Save & Print again to open printing.');}if(action==='books')emit('changed');else{dialog.value='journal';await load();}}catch(e){if(printWindow&&!printWindow.closed)printWindow.close();formError.value=(e as Error).message;if(action==='books')emit('notice',formError.value);}finally{busy.value=false;}}
async function exportCsv(){if(exporting.value)return;exporting.value=true;error.value='';try{const p=reportParams();p.set('export','csv');const r=await fetch('/accounting/api/reports?'+p,{headers:{Accept:'text/csv'}});if(!r.ok){const data=await r.json();throw Error(data.message||'Export failed.');}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='accounting-'+props.section+(props.section==='profit'?'-'+(result.value?.basis||profitBasis.value):'')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=(e as Error).message;}finally{exporting.value=false;}}
function paginate(delta:number){page.value+=delta;void load();}
useAccountingLiveRefresh(()=>load(),()=>!editor.value&&!dialog.value&&!cashReviewId.value&&!busy.value&&props.section!=='books');
useAccountingAlerts(error,formError);
</script>
<template>
<section class="ac-transactions" :class="{'ac-document-open':dialog==='journal'||dialog==='post','ac-journal-page':section==='journals'}"><div class="ac-section-heading"><div><h2>{{titles[section]}}</h2><p class="muted">{{section==='journals'?'Prepare, review and post balanced accounting entries.':section==='books'?'Set the base currency, start date and closed accounting period.':section==='audit'?'Who changed what, and when.':'Based on posted entries, including original and reversal entries.'}}</p></div><button v-if="section==='journals'&&can('journals.create')" class="button primary" :disabled="loading||busy" @click="newJournal">+ Create journal</button></div>
<p v-if="error" class="notice admin-error" role="alert">{{error}}</p>
<div v-if="section==='books'" class="ac-books-panel"><form @submit.prevent="run('books')"><p class="ac-help">Base amounts use two decimal places. Currency and start date become fixed after the first journal. Closing a period prevents further posting to that date or earlier.</p><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><div class="ac-form-grid"><label>Base currency<AccountingSelect><select v-model="settings.currency" :disabled="!can('books.manage')||busy"><option v-for="code in ['PKR','USD','EUR','GBP','AED','SAR','CAD','AUD']" :key="code">{{code}}</option></select></AccountingSelect></label><label>Books start date<input v-model="settings.start_date" type="date" required :max="today" :disabled="!can('books.manage')||busy"></label><label>Lock entries through<input v-model="settings.locked_through" type="date" :min="settings.start_date" :max="today" :disabled="!can('books.manage')||busy"><small>Optional. Closed periods cannot be reopened here.</small></label><div v-if="can('workflow.configure')" class="ac-books-approval"><span class="ac-books-approval-label">Posting approval</span><label class="ac-books-approval-option" :class="{enabled:settings.approval_required}"><input v-model="settings.approval_required" type="checkbox" :disabled="busy||!isSuperAdmin" aria-label="Require approval before posting"><span><strong>Require approval before posting</strong><small>Voucher: CEO-signed paper &rarr; Finance upload &rarr; Finance Head verification. Invoices and payment requests use online approval.</small></span></label></div></div><section v-if="can('workflow.configure')" class="ac-approval-scope"><div><h3>Company approval workflow</h3><p>Only Super Admin can change this policy. Changes apply only to the selected company. Tick the document types that must complete approval before posting. Existing pending approvals keep their current workflow until completed or withdrawn. Unticked types use normal manual posting; all unposted drafts stay out of financial reports.</p></div><fieldset class="ac-journal-fields" :disabled="busy||!settings.approval_required||!isSuperAdmin"><div class="ac-approval-scope-grid"><label v-for="type in approvalTypes" :key="type.key" :class="{selected:settings.approval_types?.includes(type.key)}"><input v-model="settings.approval_types" type="checkbox" :value="type.key"><span><strong>{{type.name}}</strong><small>{{type.paper?'CEO-signed copy + Finance Head verification':'Online Finance / CEO approval'}}</small></span></label></div></fieldset><p v-if="!settings.approval_required" class="muted">Enable posting approval above to apply these selections.</p><p v-else-if="!settings.approval_types?.length" class="muted">No types selected. All documents use normal manual posting.</p></section><section class="ac-approval-scope"><h3>Company expense voucher hours</h3><p>Daily creation and draft saving window for EV and entries debiting expense accounts (including cash/bank payment vouchers), in Pakistan time (Asia/Karachi). Closing time is exclusive. Super Admin is exempt; only Super Admin can change these hours.</p><div class="ac-form-grid"><label>Opens at<input v-model="settings.expense_open_time" type="time" required :disabled="!isSuperAdmin||busy"></label><label>Closes at<input v-model="settings.expense_close_time" type="time" required :disabled="!isSuperAdmin||busy"></label></div></section><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><button v-if="can('books.manage')" class="button primary" :disabled="busy"><span v-if="busy" class="ac-spinner"></span>{{busy?'Saving...':'Save books settings'}}</button><p v-else class="muted">An Accounting Manager manages company books settings.</p></form></div>
<template v-else><div v-if="!book&&section!=='audit'" class="ac-empty"><h3>Set up company books first</h3><p>An Accounting Manager must select the currency and books start date before transactions can be entered.</p></div>
<template v-else>
<form v-if="section==='journals'" class="ac-filters" @submit.prevent="page=1;load()"><label class="ac-search">Search journals<input v-model="search" type="search" placeholder="Journal number, reference or description"></label><label>Status<AccountingSelect><select v-model="status"><option value="">All statuses</option><option value="draft">Non-posted</option><option value="posted">Posted</option><option value="reversed">Reversed</option></select></AccountingSelect></label><button class="button" :disabled="loading">Apply filters</button></form>
<form v-else-if="section!=='audit'" class="ac-filters" @submit.prevent="page=1;load()"><label v-if="section==='profit'">Accounting basis<AccountingSelect><select aria-label="Accounting basis" v-model="profitBasis"><option value="accrual">Accrual basis</option><option value="cash">Cash basis</option></select></AccountingSelect></label><label v-if="section==='trial'">Trial Balance view<AccountingSelect><select aria-label="Trial Balance view" v-model="trialColumns"><option value="2">2 columns ? Closing balances</option><option value="6">6 columns ? Opening, movement and closing</option></select></AccountingSelect></label><label v-if="section!=='balance'&&!aging&&!(section==='trial'&&trialColumns==='2')">From<input v-model="from" type="date" required></label><label>{{section==='balance'||aging||(section==='trial'&&trialColumns==='2')?'As of':'To'}}<input v-model="to" type="date" required></label><label v-if="section==='ledger'">Account<AccountingSelect><select v-model="accountId"><option value="">All ledger accounts</option><option v-for="a in allLedgers" :value="String(a.id)" :key="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label><button class="button primary" :disabled="loading">{{loading?'Loading...':'Update report'}}</button><button v-if="can('reports.export')" type="button" class="button" :disabled="exporting||loading||!result" @click="exportCsv"><span v-if="exporting" class="ac-spinner"></span>{{exporting?'Exporting...':'Download CSV'}}</button></form>
<p v-if="loading" role="status">Loading accounting records...</p>
<template v-if="result&&!loading"><div v-if="['ledger','trial','profit','balance','receivables','payables'].includes(section)" class="ac-stats"><template v-if="aging"><article><small>Total outstanding</small><strong>{{amount(result.summary.outstanding)}}</strong></article><article><small>{{section==='receivables'?'Received / credit adjustments':'Paid / debit adjustments'}}</small><strong>{{amount(section==='receivables'?result.summary.ledger_credit:result.summary.ledger_debit)}}</strong></article><article><small>Open invoice balance</small><strong>{{amount(result.summary.invoice_outstanding)}}</strong></article><article><small>Not overdue</small><strong>{{amount(result.summary.current)}}</strong></article><article><small>1-30 days overdue</small><strong>{{amount(result.summary.days_1_30)}}</strong></article><article><small>31-60 days overdue</small><strong>{{amount(result.summary.days_31_60)}}</strong></article><article><small>61-90 days overdue</small><strong>{{amount(result.summary.days_61_90)}}</strong></article><article><small>Over 90 days</small><strong>{{amount(result.summary.over_90)}}</strong></article></template><template v-else-if="section==='profit'"><article><small>Income</small><strong>{{amount(result.summary.income)}}</strong></article><article><small>Expenses</small><strong>{{amount(result.summary.expense)}}</strong></article><article><small>Net profit / loss</small><strong>{{amount(result.summary.profit)}}</strong></article></template><template v-else-if="section==='balance'"><article><small>Assets</small><strong>{{amount(result.summary.assets)}}</strong></article><article><small>Liabilities</small><strong>{{amount(result.summary.liabilities)}}</strong></article><article><small>Equity + earnings</small><strong>{{amount(Number(result.summary.equity)+Number(result.summary.accumulated_earnings))}}</strong></article><article><small>Equation difference</small><strong>{{amount(result.summary.balance_difference)}}</strong></article></template><template v-else-if="section==='trial'&&trialColumns==='2'"><article><small>Closing debits</small><strong>{{trialTotal('closing_debit')}}</strong></article><article><small>Closing credits</small><strong>{{trialTotal('closing_credit')}}</strong></article><article><small>Closing difference</small><strong>{{amount(result.summary.closing_difference)}}</strong></article></template><template v-else><article v-if="section==='ledger'"><small>Opening debit balance</small><strong>{{amount(result.opening)}}</strong></article><article><small>Period debits</small><strong>{{amount(section==='trial'?result.summary.debit:result.debit)}}</strong></article><article><small>Period credits</small><strong>{{amount(section==='trial'?result.summary.credit:result.credit)}}</strong></article><article><small>{{section==='trial'?'Closing difference':'Closing debit balance'}}</small><strong>{{amount(section==='trial'?result.summary.closing_difference:result.closing)}}</strong></article></template></div>
<header v-if="result.currency&&!['profit','balance'].includes(section)" class="ac-report-title"><strong>{{companyName}}</strong><h3>{{titles[section]}}</h3><span>{{aging||(section==='trial'&&trialColumns==='2')?'As at '+result.to:result.from+' to '+result.to}}</span></header><p v-if="result.currency" class="muted ac-report-caption">All amounts in {{result.currency}}. {{section==='balance'?'Includes accumulated earnings through the selected date.':section==='ledger'?'Running balances use debit-positive and credit-negative amounts.':section==='trial'?(trialColumns==='2'?'Closing debit and credit balances at the selected date.':'Opening debit/credit, period movements and closing debit/credit balances.'):''}}</p>
<div v-if="aging&&result?.summary?.unallocated_adjustments&&Number(result.summary.unallocated_adjustments)!==0" class="ac-help" role="status"><strong>Ledger balance: {{amount(result.summary.ledger_balance)}}</strong><p>Open invoice balance: {{amount(result.summary.invoice_outstanding)}}. Receipts / other ledger adjustments not allocated to invoices: {{amount(result.summary.unallocated_adjustments)}}. The total includes posted customer/supplier ledger entries. The invoice rows and ageing buckets below show invoice allocations only; record an invoice payment against its invoice to update its paid and remaining amounts.</p></div>
<div v-if="section==='profit'&&result.basis==='cash'&&result.cash_basis_review?.length" class="ac-help ac-cash-review" role="status"><strong>Cash-basis review needed: {{result.cash_basis_review.length}} manual entries excluded.</strong><p>These entries do not identify how cash relates to income or expenses. Review their allocation before using these totals as a complete report.</p><details><summary>Show entries requiring review</summary><div class="ac-review-list"><article v-for="entry in result.cash_basis_review" :key="entry.id"><div><button type="button" class="ac-review-entry" :disabled="!can('cash_reviews.view')" @click="cashReviewId=entry.id">{{entry.number}}</button><span>{{entry.posting_date}}</span><strong v-if="entry.net_cash">{{result.currency}} {{amount(Math.abs(Number(entry.net_cash)))}}</strong><p>{{entry.description||entry.reason}}</p></div><button type="button" class="button" :disabled="!can('cash_reviews.view')" @click="cashReviewId=entry.id">{{canManage?'Review & resolve':'View entry'}}</button></article></div></details></div><details v-if="section==='profit'&&result.basis==='cash'&&result.cash_basis_resolved?.length" class="ac-help"><summary>Reviewed cash-basis entries ({{result.cash_basis_resolved.length}})</summary><div class="ac-review-list"><article v-for="entry in result.cash_basis_resolved" :key="entry.id"><div><button type="button" class="ac-review-entry" :disabled="!can('cash_reviews.view')" @click="cashReviewId=entry.id">{{entry.number}}</button><span>{{entry.posting_date}}</span><p>{{entry.decision==='outside'?'Outside Profit and Loss':'Allocated to income / expense'}} &middot; Reviewed by {{entry.reviewed_by}}</p></div><button class="button" type="button" :disabled="!can('cash_reviews.view')" @click="cashReviewId=entry.id">View review</button></article></div></details><AccountingStatement v-if="['profit','balance'].includes(section)" :report="section" :result="result" :company-name="companyName" @account="emit('ledger',$event)"/><div v-else class="ac-table-wrap"><table class="ac-finance-table"><thead><tr v-if="section==='journals'"><th>Journal</th><th>Date</th><th>Description</th><th>Status</th><th class="numeric">Total</th><th>Action</th></tr><tr v-else-if="section==='audit'"><th>Person</th><th>Action</th><th>Record</th><th>When</th></tr><tr v-else-if="aging"><th>Invoice</th><th>Contact</th><th>Due date</th><th class="numeric">Overdue days</th><th class="numeric">Total</th><th class="numeric">Paid</th><th class="numeric">Outstanding</th></tr><tr v-else-if="section==='ledger'"><th>Date</th><th>Journal</th><th>Account</th><th>Description</th><th class="numeric">Debit</th><th class="numeric">Credit</th><th class="numeric">Balance</th></tr><tr v-else><th>Account</th><th>Type</th><template v-if="section==='trial'"><th v-for="field in trialFields" :key="field.key" class="numeric">{{field.label}}</th></template><th v-else class="numeric">Amount</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id||row.account_id||index"><template v-if="section==='journals'"><td><strong>{{row.number}}</strong><small>{{row.kind==='opening'?'Opening balances':row.reversal_of?'Reversal entry':row.reference}}</small></td><td>{{row.posting_date}}</td><td class="ac-description-cell">{{row.remarks}}</td><td><span class="ac-badge" :class="row.status==='posted'?'active':'inactive'">{{row.status==='draft'?'Non-posted':row.status}}</span></td><td class="numeric">{{amount(row.total)}}</td><td><button class="button" @click="view(row)">{{row.status==='draft'&&can('journals.update')?'Edit draft':'View entry'}}</button></td></template><template v-else-if="section==='audit'"><td>{{row.actor_name}}</td><td>{{row.action}}</td><td>{{row.subject}}</td><td>{{new Date(row.created_at).toLocaleString()}}</td></template><template v-else-if="aging"><td>{{row.number}}</td><td>{{row.party_name}}</td><td>{{row.due_date}}</td><td class="numeric">{{row.overdue_days}}</td><td class="numeric">{{amount(row.total)}}</td><td class="numeric">{{amount(row.paid)}}</td><td class="numeric">{{amount(row.outstanding)}}<small v-if="row.original_currency">{{row.original_currency}} {{amount(row.original_outstanding)}}</small></td></template><template v-else-if="section==='ledger'"><td>{{row.posting_date}}</td><td>{{row.number}}</td><td>{{row.code}} - {{row.name}}<small v-if="section==='ledger'&&row.currency">{{row.currency}} Dr {{amount((row.foreign_debit_minor||0)/100)}} / Cr {{amount((row.foreign_credit_minor||0)/100)}} &middot; Rate {{row.exchange_rate}}</small></td><td class="ac-description-cell">{{row.remarks}}</td><td class="numeric">{{amount(row.debit)}}</td><td class="numeric">{{amount(row.credit)}}</td><td class="numeric">{{amount(row.balance)}}</td></template><template v-else><td>{{row.code}} - {{row.name}}<small v-if="section==='ledger'&&row.currency">{{row.currency}} Dr {{amount((row.foreign_debit_minor||0)/100)}} / Cr {{amount((row.foreign_credit_minor||0)/100)}} &middot; Rate {{row.exchange_rate}}</small></td><td>{{row.root_type}}</td><template v-if="section==='trial'"><td v-for="field in trialFields" :key="field.key" class="numeric">{{amount(row[field.key])}}</td></template><td v-else class="numeric">{{amount(row.amount)}}</td></template></tr><tr v-if="section==='balance'"><td><strong>Accumulated earnings</strong></td><td>Equity</td><td class="numeric">{{amount(result.summary.accumulated_earnings)}}</td></tr><tr v-if="!rows.length"><td colspan="8" class="ac-empty-small">No records for these filters.</td></tr></tbody><tfoot v-if="section==='trial'"><tr class="ac-trial-total"><th colspan="2">Total</th><th v-for="field in trialFields" :key="field.key" class="numeric">{{trialTotal(field.key)}}</th></tr></tfoot></table></div>
<div v-if="['journals','ledger','audit','receivables','payables'].includes(section)" class="ac-pagination"><span>Page {{page}} of {{lastPage}} &middot; {{section==='ledger'?result.entries.total:result.total}} records</span><button class="button" :disabled="page<=1||loading" @click="paginate(-1)">Previous</button><button class="button" :disabled="page>=lastPage||loading" @click="paginate(1)">Next</button></div></template></template></template>
<component :is="(dialog==='journal'||dialog==='post')?AccountingDocument:AdminDialog" v-if="dialog&&editor" :title="dialog==='reverse'?'Reverse journal':editor.id?editor.number:'Create journal entry'" :busy="busy" dialog-class="ac-dialog ac-journal-dialog" @close="!busy&&(dialog='')"><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><form v-if="dialog==='reverse'" @submit.prevent="run('reverse')"><p>The original entry stays in the ledger. An opposite entry is posted on the selected open date.</p><label>Reversal date<input v-model="reverseDate" type="date" required :min="editor.posting_date" :max="today"></label><label>Reason<textarea v-model="reason" required minlength="5" maxlength="2000"></textarea></label><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="dialog='journal'">Back</button><button class="button primary" :disabled="busy">{{busy?'Reversing...':'Confirm reversal'}}</button></div></form>
<form v-else @submit.prevent="run('save')"><div v-if="!ledgerAccounts.length" class="ac-help" role="status"><strong>{{accounts.length?'No active journal ledger accounts are available.':'Set up this company’s chart of accounts.'}}</strong><p>Journal entries need active ledger accounts in {{companyName}}. Group accounts cannot receive journal postings.</p><button v-if="can('chart.view')" type="button" class="button primary" @click="dialog='';emit('chart')">Open Chart of accounts</button><p v-else>Ask your Accounting Manager to set up or activate the ledger accounts.</p></div><div v-if="!book" class="ac-help" role="status"><strong>Set up company books before saving entries.</strong><p>Select the base currency and books start date for {{companyName}}.</p><button type="button" class="button primary" @click="emit('setup')">Open Company books</button></div><p class="ac-help">{{draft?'Non-posted draft: no ledger effect. Save changes before reviewing and posting.':'Posted entries cannot be edited. Corrections require a reversal.'}} Amounts in {{book?.currency}}.</p><p v-if="editor.lines?.some((line:any)=>accounts.some(a=>a.id===line.account_id&&['Receivable','Payable'].includes(a.account_type)))" class="ac-help">This journal adjusts the ledger balance. To settle a specific customer or supplier invoice, record its payment from that invoice.</p><fieldset :disabled="busy||!book||!draft||!mayEdit||dialog==='post'" class="ac-journal-fields"><div class="ac-form-grid"><label>Posting date<input v-model="editor.posting_date" type="date" required :max="voucherSuperAdmin?undefined:today" :min="book?.start_date"></label><label>Entry type<AccountingSelect><select v-model="editor.kind"><option value="general">General journal</option><option value="opening">Opening balances</option><option v-if="editor.kind==='reversal'" value="reversal">Reversal</option></select></AccountingSelect></label><label>Reference<input v-model="editor.reference" maxlength="150"></label><label>Description <span class="muted">(optional)</span><textarea aria-label="Description" v-model="editor.remarks" maxlength="2000" rows="2"></textarea></label></div><AccountingCurrencyFields :model="editor" :company="company" :base="book?.currency||'PKR'" :date="editor.posting_date"/><div class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Ledger account</th><th>Debit</th><th>Credit</th><th>Line note</th><th></th></tr></thead><tbody><tr v-for="(line,index) in (editor.lines as any[])" :key="index" @keydown.enter="addRowOnEnter($event,index,editor.lines,()=>({account_id:'',debit:'0.00',credit:'0.00',description:''}),!!book&&draft&&mayEdit&&!busy&&dialog==='journal')"><td><AccountingSelect><select v-model.number="line.account_id" required :aria-label="'Account line '+(index+1)"><option value="" disabled>Select account</option><option v-if="!ledgerAccounts.some(a=>a.id===line.account_id)&&line.account_id" :value="line.account_id">{{line.account_code}} - {{line.account_name}}</option><option v-for="a in ledgerAccounts" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></td><td><input class="ac-money-input" :title="Number(line.credit)>0?'Clear the credit amount to enter a debit.':undefined" :value="line.debit" :disabled="Number(line.credit)>0" @focus="selectZero" @click="selectZero" @beforeinput="guardAmount" @input="amountInput($event,line,'debit')" @blur="finishAmount(line,'debit')" type="text" inputmode="decimal" required pattern="[0-9]{1,10}(\.[0-9]{1,2})?" :aria-label="'Debit line '+(index+1)"></td><td><input class="ac-money-input" :title="Number(line.debit)>0?'Clear the debit amount to enter a credit.':undefined" :value="line.credit" :disabled="Number(line.debit)>0" @focus="selectZero" @click="selectZero" @beforeinput="guardAmount" @input="amountInput($event,line,'credit')" @blur="finishAmount(line,'credit')" type="text" inputmode="decimal" required pattern="[0-9]{1,10}(\.[0-9]{1,2})?" :aria-label="'Credit line '+(index+1)"></td><td><input v-model="line.description" maxlength="250" :aria-label="'Note line '+(index+1)"></td><td><button v-if="draft&&mayEdit" type="button" class="button ac-danger" :disabled="editor.lines.length<=2" :aria-label="'Remove line '+(index+1)" @click="editor.lines.splice(index,1)">&times;</button></td></tr></tbody></table></div><button v-if="draft&&mayEdit" type="button" class="button" :disabled="editor.lines.length>=100" @click="editor.lines.push({account_id:'',debit:'0.00',credit:'0.00',description:''})">+ Add line</button></fieldset><div class="ac-journal-totals"><span>Currency <strong>{{editor.currency||book?.currency}}</strong></span><span>Base equivalent <strong>{{book?.currency}} {{amount(debit/100*Number(editor.exchange_rate||1))}}</strong></span><span>Debit <strong>{{amount(debit/100)}}</strong></span><span>Credit <strong>{{amount(credit/100)}}</strong></span><span :class="balanced?'ac-success':'ac-danger'">{{balanced?'Balanced':'Difference: '+amount((debit-credit)/100)}}</span></div><div v-if="dialog!=='post'" class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="dialog=''">Close</button><button v-if="draft&&mayEdit" class="button primary" :disabled="busy||!book||!balanced"><span v-if="busy" class="ac-spinner"></span>{{busy?'Saving...':'Save draft'}}</button><button v-if="draft&&mayEdit&&can('journals.print')" type="button" class="button" :disabled="busy||!book||!balanced" @click="saveAndPrint"><span v-if="busy" class="ac-spinner"></span>Save &amp; Print</button><a v-if="editor.id&&can('journals.print')&&(!draft||!mayEdit)" class="button" :href="journalPrintUrl(editor)" target="_blank" rel="noopener">{{draft?'Print draft':'Print journal'}}</a><button v-if="draft&&can('journals.post')&&editor.id&&!requiresApproval&&!approvalPending" type="button" class="button" :disabled="busy" @click="reviewPosting">Review posting</button><button v-if="editor.status==='posted'&&!editor.reversal_of&&can('journals.reverse')" type="button" class="button ac-danger" :disabled="busy" @click="dialog='reverse';reason='';reverseDate=today">Reverse entry</button></div></form><AccountingApprovalPanel v-if="editor.id&&(requiresApproval||editor.approval)&&(editor.status==='draft'||editor.approval)&&can('workflow.view')" :company="company" type="journal" :document-id="editor.id" :version="editor.version" :csrf="csrf" :unsaved="unsaved" @notice="emit('notice',$event)" @changed="view(editor)"/>
<div v-if="dialog==='post'" class="ac-post-confirm"><p>Posting uses the last <strong>saved</strong> version and permanently records these entries in the ledger. Save any edits before posting.</p><button class="button primary" :disabled="busy" @click="run('post')">{{busy?'Posting...':'Confirm posting saved entry'}}</button><button class="button" :disabled="busy" @click="dialog='journal'">Back to draft</button></div></component>
<CashBasisReview v-if="cashReviewId" :entry-id="cashReviewId" :company="company" :accounts="accounts" :csrf="csrf" @close="cashReviewId=null" @saved="reviewSaved"/></section>
</template>
